changeSet.sql:
DELETE FROM subscription
WHERE (subscription_id, start_date) IN (
  SELECT subscription_id, start_date
  FROM (
    SELECT subscription_id, start_date,
           ROW_NUMBER() OVER (
             PARTITION BY subscription_number, start_date
             ORDER BY subscription_id DESC
           ) AS rn
    FROM subscription
    WHERE subscription_number IS NOT NULL AND TRIM(subscription_number) <> ''
  ) t
  WHERE t.rn > 1
);

DELETE FROM subscription
WHERE subscription_number IS NULL OR TRIM(subscription_number) = '';

UPDATE subscription_measurements sm
SET subscription_number = (
  SELECT s.subscription_number FROM subscription s
  WHERE s.subscription_id = sm.subscription_id AND s.start_date = sm.start_date
);

DELETE FROM subscription_measurements
WHERE subscription_number IS NULL OR TRIM(subscription_number) = '';
